export async function recall(query, { limit = 6 } = {}) {
  const hits = index.search(query).slice(0, Math.min(limit, 10));
  return hits.map((h) => `- [${h.path}#${h.heading}] ${h.snippet}`).join("\n");
}

def parse_date(s: str) -> datetime:
    """Parse an ISO date."""
    return datetime.fromisoformat(s.replace("Z", "+00:00"))


if __name__ == "__main__":
    print(parse_date("2026-10-27T19:40:12Z"))
